// internal/restful/v2/entity.go line 95-140
func (h *EntityHandler) Insert(ctx context.Context, req *restful.InsertReq) (*restful.InsertResp, error) {
    // Per-field type coercion for flexible REST v2 API
    for _, entity := range req.Data {
        for fieldName, fieldValue := range entity {
            switch fieldSchema.DataType {
            case schema.Int64:
                if strVal, ok := fieldValue.(string); ok {
                    if intVal, err := strconv.ParseInt(strVal, 10, 64); err == nil {
                        entity[fieldName] = intVal  // String to Int64
                    }
                }
            case schema.VarChar:
                if intVal, ok := fieldValue.(int); ok {
                    entity[fieldName] = strconv.Itoa(intVal)  // Int to VarChar
                }
            case schema.Bool:
                if strVal, ok := fieldValue.(string); ok {
                    if boolVal, err := strconv.ParseBool(strVal); err == nil {
                        entity[fieldName] = boolVal  // String to Bool
                    }
                }
            }
        }
    }
    return m.Insert(ctx, collectionName, partitionName, req.Data)
}
